/* ---------------- A real screen definition vs screen.yaml ---------------- */
const yamlShort = () => {
  const W = 36, L = D.yaml.text.split('\n'), out = [];
  const trim = (l) => (l.length > W ? l.slice(0, W - 1) + '…' : l);
  let block = null, nb = 0, nf = 0, skipped = 0;
  const flush = () => { if (block) out.push(`${block} … ${nb} lines`); if (skipped) out.push(`  … ${skipped} more fields`); block = null; nb = 0; skipped = 0; };
  for (const l of L) {
    const top = /^[a-z_]+:/.test(l);
    if (top) { flush(); }
    if (/^(help|state):/.test(l)) { block = l.split(':')[0] + ':'; continue; }
    if (block) { nb++; continue; }
    if (/^\s*- \{name:/.test(l)) { nf++; if (nf <= 2) out.push(trim(l)); else skipped++; continue; }
    if (skipped && !/^\s*- \{name:/.test(l)) { out.push(`  … ${skipped} more fields`); skipped = 0; }
    out.push(trim(l));
  }
  flush();
  return out.join('\n');
};
