/* ---------------- Granularity results ---------------- */
FIGS.gran = (el) => {
  const { svgEl, txt } = P();
  let tier = 'gemini:gemini-3.8-flash', kk = 4;
  el.innerHTML = `${btns('grt', Object.entries(TIERS), tier)}<div class="grs"></div>`;
  const host = el.querySelector('.grs');
  const mets = [['passed', 'Tasks passed (of 30)', (v) => v], ['tokens_mean', 'Tokens per task', num], ['inr_mean', '₹ per task', (v) => inr(v)], ['seconds_mean', 'Model seconds per task', (v) => v.toFixed(1)], ['tool_calls_mean', 'Tool calls per task', (v) => v.toFixed(1)]];
  const render = () => {
    host.innerHTML = '';
    const W = 1400, H = 560, cw = W / mets.length, g = D.gran[tier], cfgs = Object.keys(CFG);
    const svg = svgEl('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, host);
    mets.forEach(([key, lab, f], mi) => {
      const gx = mi * cw + 16, mx = Math.max(...cfgs.map((c) => g[c][key])) || 1, top = 70, bh = 360;
      const grp = svgEl('g', { style: `opacity:${mi <= kk ? 1 : 0.08};transition:opacity .4s` }, svg);
      txt(grp, gx, 34, lab, 'font:600 19px var(--serif);fill:var(--ink)');
      cfgs.forEach((c, ci) => {
        const v = g[c][key], h = bh * v / mx, x = gx + ci * 62, y = top + bh - h;
        svgEl('rect', { x, y, width: 50, height: h, style: `fill:${CFG[c][1]}` }, grp);
        txt(grp, x + 25, y - 8, f(v), 'font:600 18px var(--mono);fill:var(--ink)', 'middle');
      });
    });
    cfgs.forEach((c, ci) => { svgEl('rect', { x: 16 + ci * 340, y: H - 40, width: 22, height: 22, style: `fill:${CFG[c][1]}` }, svg); txt(svg, 46 + ci * 340, H - 22, CFG[c][0], 'font:19px var(--serif);fill:var(--ink)'); });
  };
  wire(el, 'grt', (t) => { tier = t; render(); });
  render();
  return { step(k) { kk = [0, 1, 2, 4][Math.min(k, 3)]; render(); } };
};

